import{_ as t,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"应用 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":4,"title":"绑定到容器","slug":"绑定到容器","link":"#绑定到容器","children":[]},{"level":4,"title":"从容器中解析","slug":"从容器中解析","link":"#从容器中解析","children":[]},{"level":4,"title":"将\\"共享\\"类型绑定到容器","slug":"将-共享-类型绑定到容器","link":"#将-共享-类型绑定到容器","children":[]},{"level":4,"title":"将现有实例绑定到容器","slug":"将现有实例绑定到容器","link":"#将现有实例绑定到容器","children":[]},{"level":4,"title":"将接口绑定到实现","slug":"将接口绑定到实现","link":"#将接口绑定到实现","children":[]},{"level":3,"title":"注册绑定的位置","slug":"注册绑定的位置","link":"#注册绑定的位置","children":[]},{"level":2,"title":"服务提供者","slug":"服务提供者","link":"#服务提供者","children":[{"level":4,"title":"定义服务提供者","slug":"定义服务提供者","link":"#定义服务提供者","children":[]},{"level":4,"title":"在运行时注册服务提供者","slug":"在运行时注册服务提供者","link":"#在运行时注册服务提供者","children":[]}]},{"level":2,"title":"应用事件","slug":"应用事件","link":"#应用事件","children":[{"level":4,"title":"请求事件","slug":"请求事件","link":"#请求事件","children":[]},{"level":4,"title":"容器事件","slug":"容器事件","link":"#容器事件","children":[]}]},{"level":2,"title":"应用助手","slug":"应用助手","link":"#应用助手","children":[{"level":4,"title":"获取应用环境","slug":"获取应用环境","link":"#获取应用环境","children":[]},{"level":4,"title":"确定执行上下文","slug":"确定执行上下文","link":"#确定执行上下文","children":[]}]}],"relativePath":"3.x/zh-cn/extend/services/application.md","filePath":"3.x/zh-cn/extend/services/application.md"}'),u={name:"3.x/zh-cn/extend/services/application.md"};function r(k,n,d,h,g,v){const p=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(p),n[0]||(n[0]=l("h1",null,"应用",-1)),a(e),n[1]||(n[1]=i(`<p>控制反转（IoC）容器是一个用于管理类依赖关系的工具。依赖注入是一种移除硬编码类依赖的方法。相反，依赖关系在运行时注入，从而允许更大的灵活性，因为依赖实现可以轻松地被替换。</p><h4 id="绑定到容器"><a href="#绑定到容器" class="header-anchor">#</a> 绑定到容器</h4><p>IoC 容器有两种解析依赖的方式：通过闭包回调或自动解析。首先，我们来探讨闭包回调。首先，可以将一个&quot;类型&quot;绑定到容器中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="从容器中解析"><a href="#从容器中解析" class="header-anchor">#</a> 从容器中解析</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当调用 <code>App::make</code> 方法时，闭包回调将被执行并返回结果。</p><h4 id="将-共享-类型绑定到容器"><a href="#将-共享-类型绑定到容器" class="header-anchor">#</a> 将&quot;共享&quot;类型绑定到容器</h4><p>有时你可能希望将某些内容绑定到容器中，使其只被解析一次，后续调用返回相同的实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">singleton</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将现有实例绑定到容器"><a href="#将现有实例绑定到容器" class="header-anchor">#</a> 将现有实例绑定到容器</h4><p>你也可以使用 <code>instance</code> 方法将现有的对象实例绑定到容器中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$foo</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token variable">$foo</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将接口绑定到实现"><a href="#将接口绑定到实现" class="header-anchor">#</a> 将接口绑定到实现</h4><p>在某些情况下，一个类可能依赖于接口实现，而不是&quot;具体类型&quot;。在这种情况下，必须使用 <code>App::bind</code> 方法来告知容器应注入哪个接口实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;DbUserRepository&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在考虑以下代码：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>由于我们已将 <code>UserRepositoryInterface</code> 绑定到具体类型，<code>DbUserRepository</code> 将在创建此控制器时自动注入。</p><h3 id="注册绑定的位置"><a href="#注册绑定的位置" class="header-anchor">#</a> 注册绑定的位置</h3><p>IoC 绑定，如同<a href="./event.html">事件处理程序</a>，通常属于&quot;引导代码&quot;的范畴。换句话说，它们为你的应用程序准备好实际处理请求的能力，通常需要在路由或控制器实际被调用之前执行。最常见的位置是<a href="./../extending.html">插件注册文件</a>的 <code>boot</code> 方法。另外，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，用于放置 IoC 注册逻辑。</p><h2 id="服务提供者"><a href="#服务提供者" class="header-anchor">#</a> 服务提供者</h2><p>服务提供者是创建库和在单个位置执行相关 IoC 注册的好方法。在服务提供者中，你可以注册自定义的身份验证驱动程序、将应用程序的存储库类注册到 IoC 容器中，甚至设置自定义的 Artisan 命令。</p><p>事实上，<a href="./../system/plugins.html">插件注册文件</a>继承自服务提供者，大多数核心组件都包含服务提供者。你的应用程序所有已注册的服务提供者都列在 <code>config/app.php</code> 配置文件的 <code>providers</code> 数组中。</p><h4 id="定义服务提供者"><a href="#定义服务提供者" class="header-anchor">#</a> 定义服务提供者</h4><p>要创建服务提供者，只需扩展 <code>October\\Rain\\Support\\ServiceProvider</code> 类并定义一个 <code>register</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>ServiceProvider</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FooServiceProvider</span> <span class="token keyword">extends</span> <span class="token class-name">ServiceProvider</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token operator">-&gt;</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>请注意，在 <code>register</code> 方法中，你可以通过 <code>$this-&gt;app</code> 属性访问应用程序 IoC 容器。创建提供者并准备将其注册到应用程序后，只需将其添加到 <code>app</code> 配置文件中的 <code>providers</code> 数组即可。</p><h4 id="在运行时注册服务提供者"><a href="#在运行时注册服务提供者" class="header-anchor">#</a> 在运行时注册服务提供者</h4><p>你也可以使用 <code>App::register</code> 方法在运行时注册服务提供者。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FooServiceProvider&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="应用事件"><a href="#应用事件" class="header-anchor">#</a> 应用事件</h2><h4 id="请求事件"><a href="#请求事件" class="header-anchor">#</a> 请求事件</h4><p>你可以使用 <code>before</code> 和 <code>after</code> 方法在请求被路由之前注册特殊事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 在请求被路由之前执行的代码</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 在请求被路由之后执行的代码</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="容器事件"><a href="#容器事件" class="header-anchor">#</a> 容器事件</h4><p>服务容器每次解析对象时都会触发一个事件。你可以使用 <code>resolving</code> 方法来监听此事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$object</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器解析任何类型的对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器使用提示 &quot;foo&quot; 解析对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme\\Blog\\Classes\\FooBar&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器解析类型为 &quot;FooBar&quot; 的对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如你所见，被解析的对象将传递给回调，允许你在将对象交给其使用者之前设置任何附加属性。</p><h2 id="应用助手"><a href="#应用助手" class="header-anchor">#</a> 应用助手</h2><h4 id="获取应用环境"><a href="#获取应用环境" class="header-anchor">#</a> 获取应用环境</h4><p>你可以使用 <code>environment</code> 方法来获取由<a href="./../../setup/configuration.html">环境配置</a>确定的应用环境。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// production</span>
<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">environment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="确定执行上下文"><a href="#确定执行上下文" class="header-anchor">#</a> 确定执行上下文</h4><p>可以使用 <code>runningInBackend</code> 方法来判断当前请求是否在后台管理区域执行。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInBackend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以使用 <code>runningInConsole</code> 方法来检查正在执行的代码是否在<a href="./../console-commands.html">命令行界面</a>中运行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInConsole</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,48))])}const x=t(u,[["render",r]]);export{m as __pageData,x as default};
